graph = {0: [(1, 1), (2, 4)], 1: [(2, 2), (3, 6)], 2: [(3, 3)], 3: []}
dist = {0: 0, 1: 10**9, 2: 10**9, 3: 10**9}
used = set()
order = []
while len(order) < 4:
    u = min((v for v in dist if v not in used), key=lambda v: dist[v])
    used.add(u)
    order.append(u)
    for v, weight in graph[u]:
        if dist[u] + weight < dist[v]:
            dist[v] = dist[u] + weight
assert order == [0, 1, 2, 3]
assert [dist[i] for i in range(4)] == [0, 1, 3, 6]
assert sum(dist.values()) == 10
# Negative edge: freezing a settled vertex reports 3; the true path weighs 2.
neg = {"s": [("a", 4), ("b", 3)], "a": [("b", -2)], "b": []}
nd = {"s": 0, "a": 10**9, "b": 10**9}
seen = set()
while len(seen) < 3:
    u = min((v for v in nd if v not in seen), key=lambda v: nd[v])
    seen.add(u)
    for v, weight in neg[u]:
        if v in seen:
            continue
        if nd[u] + weight < nd[v]:
            nd[v] = nd[u] + weight
assert nd["b"] == 3 and min(3, 4 + (-2)) == 2
print(order, [dist[i] for i in range(4)], nd["b"])
